        while self._qtLayoutCount(navigationLayout):
            navigationLayout.takeAt(0)
        navigationLayout.setContentsMargins(4, 4, 4, 4)
        navigationLayout.setHorizontalSpacing(4)
        navigationLayout.setVerticalSpacing(4)
